+        for i in (0..261).rev() {
+            // The step's doubling is fused into its first nonzero digit.
+            let mut doubled = false;
+            for (table, naf) in affine.chunks_exact(8).zip(&nafs) {
+                let digit = naf[i];
+                let entry = if digit > 0 {
+                    table[(digit >> 1) as usize]
+                } else if digit < 0 {
+                    -table[((-digit) >> 1) as usize]
+                } else {
+                    continue;
+                };
+                out = if doubled {
+                    out.add_mixed(entry)
+                } else {
+                    doubled = true;
+                    out.double_add_mixed(entry)
+                };
+            }
+            if !doubled {
+                out = out.double();
+            }
+        }
